(()=>{const reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`body{background:radial-gradient(ellipse at 50% 18%,#4a1d32 0,#180b14 38%,#050408 100%)}body:before{content:'';position:fixed;inset:0;pointer-events:none;z-index:-2;background:radial-gradient(circle at 50% 45%,#f0b7c814,transparent 38%),linear-gradient(115deg,transparent 25%,#d8ac8810 50%,transparent 75%)}.fxbar{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fxbar i{display:block;height:100%;width:0;background:#f0b7c8;box-shadow:0 0 18px #f0b7c8}.fx-orb{position:fixed;border-radius:50%;pointer-events:none;filter:blur(100px);opacity:.16;z-index:-1}.fx-orb.a{width:460px;height:460px;left:-190px;top:10%;background:#a83e68;animation:drift 18s ease-in-out infinite}.fx-orb.b{width:400px;height:400px;right:-180px;bottom:4%;background:#d7a37f;animation:drift 23s ease-in-out infinite reverse}.fx-petal{position:fixed;top:-12vh;pointer-events:none;z-index:2;width:clamp(12px,1.3vw,22px);height:clamp(17px,1.8vw,30px);background:linear-gradient(135deg,#ffd0dc 0 18%,#d96b91 48%,#7d294b 100%);border-radius:100% 0 100% 0;opacity:0;filter:drop-shadow(0 4px 7px #3d0d2455);animation:petal linear infinite}.fx-mote{position:fixed;width:3px;height:3px;border-radius:50%;background:#ffeaf1;box-shadow:0 0 14px 3px #f0b7c866;pointer-events:none;opacity:0;animation:mote ease-in-out infinite}.fxr{opacity:0;transform:translateY(40px);transition:1.05s cubic-bezier(.2,.8,.2,1)}.fxr.on{opacity:1;transform:none}.proposal-accepted:after{content:'♡';position:fixed;inset:0;display:grid;place-items:center;z-index:80;pointer-events:none;font-size:min(35vw,240px);color:#f0b7c8;text-shadow:0 0 55px #fff;animation:accept .9s ease both}@keyframes petal{0%{transform:translate3d(0,-10vh,0) rotate(0) scale(.75);opacity:0}12%{opacity:.8}38%{transform:translate3d(50px,38vh,0) rotate(150deg) scale(1)}68%{transform:translate3d(-80px,75vh,0) rotate(300deg) scale(.9)}100%{transform:translate3d(45px,118vh,0) rotate(500deg) scale(.7);opacity:0}}@keyframes mote{0%,100%{transform:translate3d(0,30px,0);opacity:0}30%{opacity:.75}65%{transform:translate3d(35px,-90px,0);opacity:.25}}@keyframes drift{50%{transform:translate(90px,-55px)}}@keyframes accept{0%{opacity:0;transform:scale(.5)}45%{opacity:1;transform:scale(1.12)}100%{opacity:0;transform:scale(1.4)}}@media(prefers-reduced-motion:reduce){.fx-petal,.fx-mote{display:none}}`;b.appendChild(s);const bar=document.createElement('div');bar.className='fxbar';bar.innerHTML='<i></i>';b.appendChild(bar);['a','b'].forEach(c=>{const o=document.createElement('div');o.className='fx-orb '+c;b.appendChild(o)});if(!reduce){for(let i=0;i<24;i++){const p=document.createElement('i');p.className='fx-petal';p.style.left=Math.random()*100+'%';p.style.animationDuration=9+Math.random()*10+'s';p.style.animationDelay=-Math.random()*16+'s';p.style.transform=`scale(${.55+Math.random()*1.05})`;b.appendChild(p)}for(let i=0;i<34;i++){const m=document.createElement('i');m.className='fx-mote';m.style.left=Math.random()*100+'%';m.style.top=15+Math.random()*80+'%';m.style.animationDuration=5+Math.random()*7+'s';m.style.animationDelay=-Math.random()*8+'s';b.appendChild(m)}}document.querySelectorAll('section').forEach(e=>e.classList.add('fxr'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fxr').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.firstElementChild.style.width=(m?scrollY/m*100:0)+'%'})})();